### Base Adapter Interface

**IProtocolAdapter.cs:**

```csharp
using System.Threading;
using System.Threading.Tasks;

/// <summary>
/// Base interface for all protocol adapters
/// </summary>
/// <typeparam name="TProtocolMessage">Protocol-specific message type</typeparam>
/// <typeparam name="TEvent">Integration event type</typeparam>
public interface IProtocolAdapter<TProtocolMessage, TEvent>
{
    /// <summary>
    /// Convert protocol message to integration event (Inbound)
    /// </summary>
    Task<TEvent> ToEventAsync(TProtocolMessage protocolMessage, CancellationToken cancellationToken = default);

    /// <summary>
    /// Convert integration event to protocol message (Outbound)
    /// </summary>
    Task<TProtocolMessage> FromEventAsync(TEvent integrationEvent, CancellationToken cancellationToken = default);

    /// <summary>
    /// Health check for protocol endpoint
    /// </summary>
    Task<bool> IsHealthyAsync(CancellationToken cancellationToken = default);
}
```

