[standards/application/integration/dotnet/STD-APP-INT-003-dotnet-protocol-adapters.md#rest-adapter-configuration]

### REST Adapter Configuration

**Program.cs (REST Adapter):**

```csharp
using Refit;
using Polly;
using Polly.Extensions.Http;
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;

var builder = WebApplication.CreateBuilder(args);

// Configure Refit REST client with Polly retry policy
builder.Services.AddRefitClient<ILegacyClaimsApi>()
    .ConfigureHttpClient(c =>
    {
        c.BaseAddress = new Uri(builder.Configuration["ProtocolAdapters:REST:Endpoints:LegacyClaimsAPI:BaseUrl"]);
        c.Timeout = TimeSpan.FromSeconds(30);
    })
    .AddPolicyHandler(GetRetryPolicy())
    .AddPolicyHandler(GetCircuitBreakerPolicy());

// Configure webhook receiver
builder.Services.AddControllers();
builder.Services.AddScoped<IWebhookSignatureValidator, HmacWebhookSignatureValidator>();
builder.Services.AddScoped<IRestToEventAdapter, RestToEventAdapter>();

// Configure AutoMapper
builder.Services.AddAutoMapper(typeof(RestToEventMappingProfile));

// Configure MassTransit for event publishing
builder.Services.AddMassTransit(x =>
{
    x.UsingKafka((context, cfg) =>
    {
        cfg.Host(builder.Configuration["Kafka:BootstrapServers"]);
    });
});

// Configure OpenTelemetry
builder.Services.AddOpenTelemetry()
    .WithTracing(tracing => tracing
        .AddAspNetCoreInstrumentation()
        .AddHttpClientInstrumentation()
        .AddSource("RestAdapter")
        .AddOtlpExporter());

// Configure health checks
builder.Services.AddHealthChecks()
    .AddCheck<RestEndpointHealthCheck>("rest-endpoint")
    .AddKafka(builder.Configuration["Kafka:BootstrapServers"]);

var app = builder.Build();

app.MapControllers();
app.MapHealthChecks("/health");

await app.RunAsync();

// Retry policy
static IAsyncPolicy<HttpResponseMessage> GetRetryPolicy()
{
    return HttpPolicyExtensions
        .HandleTransientHttpError()
        .Or<TimeoutException>()
        .WaitAndRetryAsync(
            retryCount: 3,
            sleepDurationProvider: retryAttempt =>
                TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)),
            onRetry: (outcome, timespan, retryCount, context) =>
            {
                // Log retry attempt
            });
}

// Circuit breaker policy
static IAsyncPolicy<HttpResponseMessage> GetCircuitBreakerPolicy()
{
    return HttpPolicyExtensions
        .HandleTransientHttpError()
        .CircuitBreakerAsync(
            handledEventsAllowedBeforeBreaking: 5,
            durationOfBreak: TimeSpan.FromSeconds(60));
}
```

