### gRPC Adapter Configuration

**Program.cs (gRPC Adapter):**

```csharp
using Grpc.Net.Client;
using Grpc.Core;

var builder = WebApplication.CreateBuilder(args);

// Configure gRPC client channel
var channelOptions = new GrpcChannelOptions
{
    MaxReceiveMessageSize = 10 * 1024 * 1024, // 10 MB
    MaxSendMessageSize = 10 * 1024 * 1024,
    HttpHandler = new SocketsHttpHandler
    {
        PooledConnectionIdleTimeout = TimeSpan.FromMinutes(10),
        KeepAlivePingDelay = TimeSpan.FromSeconds(60),
        KeepAlivePingTimeout = TimeSpan.FromSeconds(20),
        EnableMultipleHttp2Connections = true
    }
};

var channel = GrpcChannel.ForAddress(
    builder.Configuration["ProtocolAdapters:gRPC:Endpoints:ProviderService:Address"],
    channelOptions);

builder.Services.AddSingleton(channel);
builder.Services.AddSingleton(new ProviderService.ProviderServiceClient(channel));

// Configure adapter service
builder.Services.AddScoped<IGrpcToEventAdapter, GrpcToEventAdapter>();

// Configure MassTransit
builder.Services.AddMassTransit(x =>
{
    x.UsingKafka((context, cfg) =>
    {
        cfg.Host(builder.Configuration["Kafka:BootstrapServers"]);
    });
});

// Configure health checks
builder.Services.AddHealthChecks()
    .AddCheck<GrpcEndpointHealthCheck>("grpc-endpoint");

var app = builder.Build();
await app.RunAsync();
