### MQTT Adapter Configuration

**Program.cs (MQTT Adapter):**

```csharp
using MQTTnet;
using MQTTnet.Client;
using MQTTnet.Extensions.ManagedClient;

var builder = WebApplication.CreateBuilder(args);

// Configure MQTT Managed Client
var mqttFactory = new MqttFactory();
var managedClient = mqttFactory.CreateManagedMqttClient();

var mqttOptions = new ManagedMqttClientOptionsBuilder()
    .WithAutoReconnectDelay(TimeSpan.FromSeconds(5))
    .WithClientOptions(new MqttClientOptionsBuilder()
        .WithTcpServer(builder.Configuration["ProtocolAdapters:MQTT:Brokers:0"])
        .WithTls()
        .WithCredentials(
            builder.Configuration["ProtocolAdapters:MQTT:Credentials:Username"],
            builder.Configuration["ProtocolAdapters:MQTT:Credentials:Password"])
        .WithClientId(builder.Configuration["ProtocolAdapters:MQTT:ClientId"])
        .WithKeepAlivePeriod(TimeSpan.FromSeconds(60))
        .WithCleanSession(false)
        .Build())
    .Build();

builder.Services.AddSingleton<IManagedMqttClient>(managedClient);
builder.Services.AddHostedService<MqttAdapterHostedService>();

// Configure MassTransit
builder.Services.AddMassTransit(x =>
{
    x.UsingKafka((context, cfg) =>
    {
        cfg.Host(builder.Configuration["Kafka:BootstrapServers"]);
    });
});

var app = builder.Build();
await app.RunAsync();
