[standards/application/integration/dotnet/STD-APP-INT-003-dotnet-protocol-adapters.md#example-1-rest-webhook-receiver-with-event-publishing]

#### Example 1: REST Webhook Receiver with Event Publishing

**WebhookController.cs:**

```csharp
[ApiController]
[Route("webhooks")]
public class WebhookController : ControllerBase
{
    private readonly IWebhookSignatureValidator _signatureValidator;
    private readonly IRestToEventAdapter _adapter;
    private readonly IPublishEndpoint _publishEndpoint;
    private readonly ILogger<WebhookController> _logger;

    [HttpPost("{source}/claims")]
    public async Task<IActionResult> ReceiveClaimWebhook(
        string source,
        [FromBody] ClaimWebhookPayload payload,
        [FromHeader(Name = "X-Webhook-Signature")] string signature)
    {
        using var activity = Activity.Current;
        activity?.SetTag("webhook.source", source);

        // Validate signature
        var isValid = await _signatureValidator.ValidateAsync(
            Request.Body, signature);

        if (!isValid)
        {
            _logger.LogWarning("Invalid webhook signature from {Source}", source);
            return Unauthorized();
        }

        // Convert to event
        var integrationEvent = await _adapter.ToEventAsync(payload);

        // Publish event
        await _publishEndpoint.Publish(integrationEvent, context =>
        {
            context.CorrelationId = Guid.Parse(integrationEvent.CorrelationId);
            context.Headers.Set("webhook-source", source);
        });

        _logger.LogInformation(
            "Published ClaimEvent from webhook source {Source}, CorrelationId {CorrelationId}",
            source, integrationEvent.CorrelationId);

        return Accepted();
    }
}
```

