[standards/application/integration/dotnet/STD-APP-INT-003-dotnet-protocol-adapters.md#example-2-grpc-streaming-to-event-stream]

#### Example 2: gRPC Streaming to Event Stream

**GrpcToEventAdapter.cs:**

```csharp
public class GrpcToEventAdapter : BackgroundService
{
    private readonly ProviderServiceClient _grpcClient;
    private readonly IPublishEndpoint _publishEndpoint;
    private readonly ILogger<GrpcToEventAdapter> _logger;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                using var call = _grpcClient.StreamProviderUpdates(
                    new StreamRequest { SubscriberId = "gainwell-adapter" },
                    cancellationToken: stoppingToken);

                await foreach (var update in call.ResponseStream.ReadAllAsync(stoppingToken))
                {
                    var integrationEvent = new ProviderUpdatedEvent
                    {
                        ProviderId = update.ProviderId,
                        UpdateType = update.UpdateType,
                        Timestamp = DateTime.UtcNow,
                        CorrelationId = call.RequestHeaders.GetValue("correlation-id") ?? Guid.NewGuid().ToString()
                    };

                    await _publishEndpoint.Publish(integrationEvent, stoppingToken);

                    _logger.LogInformation(
                        "Published ProviderUpdatedEvent from gRPC stream: {ProviderId}",
                        update.ProviderId);
                }
            }
            catch (RpcException ex) when (ex.StatusCode == StatusCode.Unavailable)
            {
                _logger.LogWarning("gRPC server unavailable, retrying in 5 seconds...");
                await Task.Delay(TimeSpan.FromSeconds(5), stoppingToken);
            }
        }
    }
}
```

