[standards/application/integration/dotnet/STD-APP-INT-003-dotnet-protocol-adapters.md#example-3-mqtt-topic-to-event-conversion]

#### Example 3: MQTT Topic to Event Conversion

**MqttAdapterHostedService.cs:**

```csharp
public class MqttAdapterHostedService : IHostedService
{
    private readonly IManagedMqttClient _mqttClient;
    private readonly IPublishEndpoint _publishEndpoint;
    private readonly IConfiguration _configuration;
    private readonly ILogger<MqttAdapterHostedService> _logger;

    public async Task StartAsync(CancellationToken cancellationToken)
    {
        _mqttClient.ApplicationMessageReceivedAsync += OnMessageReceivedAsync;

        await _mqttClient.StartAsync(GetMqttOptions());

        // Subscribe to topics
        var topics = _configuration.GetSection("ProtocolAdapters:MQTT:TopicMappings")
            .Get<List<TopicMapping>>();

        foreach (var mapping in topics)
        {
            await _mqttClient.SubscribeAsync(new MqttTopicFilterBuilder()
                .WithTopic(mapping.Topic)
                .WithQualityOfServiceLevel((MQTTnet.Protocol.MqttQualityOfServiceLevel)mapping.QoS)
                .Build());

            _logger.LogInformation("Subscribed to MQTT topic {Topic} with QoS {QoS}",
                mapping.Topic, mapping.QoS);
        }
    }

    private async Task OnMessageReceivedAsync(MqttApplicationMessageReceivedEventArgs e)
    {
        try
        {
            var payload = Encoding.UTF8.GetString(e.ApplicationMessage.Payload);
            var deviceId = ExtractDeviceId(e.ApplicationMessage.Topic);

            // Parse JSON payload
            var telemetryData = JsonSerializer.Deserialize<TelemetryData>(payload);

            // Create integration event
            var integrationEvent = new DeviceTemperatureEvent
            {
                DeviceId = deviceId,
                Temperature = telemetryData.Temperature,
                Timestamp = DateTime.UtcNow,
                MqttTopic = e.ApplicationMessage.Topic,
                QoS = (int)e.ApplicationMessage.QualityOfServiceLevel
            };

            // Publish to Kafka
            await _publishEndpoint.Publish(integrationEvent);

            _logger.LogInformation(
                "Published DeviceTemperatureEvent from MQTT topic {Topic}, Device {DeviceId}",
                e.ApplicationMessage.Topic, deviceId);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing MQTT message from topic {Topic}",
                e.ApplicationMessage.Topic);
        }
    }

    private string ExtractDeviceId(string topic)
    {
        // Extract device ID from topic: devices/{deviceId}/telemetry/temperature
        var parts = topic.Split('/');
        return parts.Length > 1 ? parts[1] : "unknown";
    }

    public async Task StopAsync(CancellationToken cancellationToken)
    {
        await _mqttClient.StopAsync();
    }
}
```

