#### Example 4: Event to REST API Invocation

**EventToRestAdapter.cs:**

```csharp
public class EventToRestAdapter : IConsumer<ClaimApprovedEvent>
{
    private readonly ILegacyClaimsApi _claimsApi;
    private readonly ILogger<EventToRestAdapter> _logger;

    public async Task Consume(ConsumeContext<ClaimApprovedEvent> context)
    {
        var evt = context.Message;

        using var activity = Activity.Current;
        activity?.SetTag("claim.id", evt.ClaimId);

        try
        {
            // Convert event to REST request
            var restRequest = new UpdateClaimStatusRequest
            {
                ClaimId = evt.ClaimId,
                Status = "Approved",
                ApprovedAmount = evt.ApprovedAmount,
                ApprovalDate = evt.ApprovalDate
            };

            // Invoke REST API (Polly retry policy applied automatically)
            var response = await _claimsApi.UpdateClaimStatusAsync(
                evt.ClaimId,
                restRequest,
                await GetAuthTokenAsync());

            _logger.LogInformation(
                "Successfully invoked REST API for claim {ClaimId}, Response: {Response}",
                evt.ClaimId, response.Status);
        }
        catch (ApiException ex) when (ex.StatusCode == System.Net.HttpStatusCode.BadRequest)
        {
            _logger.LogError(ex,
                "REST API returned 400 Bad Request for claim {ClaimId}, routing to DLQ",
                evt.ClaimId);

            // Route to DLQ (don't retry client errors)
            throw;
        }
        catch (ApiException ex) when ((int)ex.StatusCode >= 500)
        {
            _logger.LogWarning(ex,
                "REST API returned {StatusCode} for claim {ClaimId}, will retry",
                ex.StatusCode, evt.ClaimId);

            // Throw to trigger MassTransit retry
            throw;
        }
    }

    private Task<string> GetAuthTokenAsync()
    {
        // OAuth2 token acquisition logic
        return Task.FromResult("bearer-token");
    }
}
```

